  ('"He didn\'t study. He failed the exam." İki cümleyi neden-sonuç ilişkisini koruyarak tek cümle yapan seçenek hangisidir?', 'He failed the exam because he didn\'t study.', ['He failed the exam although he didn\'t study.', 'He failed the exam so that he didn\'t study.', 'He failed the exam unless he didn\'t study.'], 'Çalışmamak neden, başarısızlık sonuçtur; \'because\' bu ilişkiyi doğru kurar.'),
  ('"Although she was nervous, she gave a great speech." cümlesine anlamca en yakın seçenek hangisidir?', 'She was nervous, but she gave a great speech.', ['She was nervous, so she gave a great speech.', 'She gave a great speech because she was nervous.', 'She was nervous, or she gave a great speech.'], '\'Although\' karşıtlık bildirir; bu ilişki eşgüdüm bağlacı \'but\' ile de kurulabilir.'),
  ('"The bridge was designed ___ a famous engineer." Eylemi yapan kişiyi belirtmek için boşluğa hangisi gelmelidir?', 'by', ['with', 'from', 'of'], 'Edilgen yapılarda eylemi yapan kişi ya da kurum \'by\' ile belirtilir.'),
  ('"Nine ___ ten people prefer this brand." \'Her on kişiden dokuzu\' anlamı için boşluğa hangisi gelmelidir?', 'out of', ['from in', 'in of', 'over'], 'Oran bildirirken \'out of\' kullanılır: nine out of ten.'),
  ('"Tickets cost £10 ___ person." \'Kişi başı\' anlamı için boşluğa hangisi gelmelidir?', 'per', ['for every one', 'by each', 'in a'], '\'Per\' \'başına, her biri için\' anlamındadır: per person, per hour.'),
  ('"___, did you hear that Selin is moving to Germany?" Konuşmanın akışında yeni ve ilgisiz bir konu açmak için boşluğa hangisi gelmelidir?', 'By the way', ['In the way', 'On the way', 'By way of'], '\'By the way\' \'aklıma gelmişken, bu arada\' anlamında konu değiştirmek için kullanılır.'),
  ('"I\'ll buy some bread ___ home." \'Eve giderken yolda\' anlamı için boşluğa hangisi gelmelidir?', 'on the way', ['in the way', 'by the way', 'on a way to'], '\'On the way (home/to school)\' bir yere giderken yol üzerinde anlamındadır.'),
  ('"Ali and Can are both good players, but the former is faster." cümlesinde \'the former\' kimi gösterir?', 'Ali', ['Can', 'İkisini birden', 'İkisinden başka bir oyuncuyu'], '\'The former\' sözü edilen iki öğeden ilkini, \'the latter\' ise ikincisini gösterir.'),
  ('"Some people believe the Earth is flat. Such a belief has no scientific basis." cümlesinde \'such a belief\' neyi gösterir?', 'Dünyanın düz olduğu inancını', ['Bilimsel bir kuramı', 'Bütün insanların inançlarını', 'Dünyanın yuvarlak olduğu bilgisini'], '\'Such\' önceki cümlede anlatılan şeyi \'bu tür, böyle bir\' anlamıyla yeniden gösterir.'),
  ('"Hava soğuk olmasına rağmen denize girdik." cümlesinin doğru İngilizce karşılığı hangisidir?', 'Although the weather was cold, we went into the sea.', ['Because the weather was cold, we went into the sea.', 'Despite of the weather was cold, we went into the sea.', 'Unless the weather was cold, we went into the sea.'], '\'-masına rağmen\' karşıtlık bildirir; yan cümle aldığı için \'although\' kullanılır. \'Despite\' yan cümle almaz.'),
  ('"Annem yemek yaparken ben sofrayı kurdum." cümlesindeki \'-ken\' ekinin İngilizcedeki karşılığı hangisidir?', 'while', ['until', 'unless', 'since'], '\'-ken\' eki iki eylemin eş zamanlı olduğunu anlatır ve \'while\' ile karşılanır: While my mother was cooking, I laid the table.'),
  ('"Kapıyı açar açmaz kedi dışarı fırladı." cümlesindeki \'-ar -maz\' yapısının İngilizce karşılığı hangisidir?', 'as soon as', ['as long as', 'as well as', 'as far as possible'], '\'-r -mez\' iki olayın hemen ardı ardına olduğunu anlatır ve \'as soon as\' ile karşılanır.'),
  ('"Ne annem ne de babam İngilizce konuşur." cümlesinin doğru İngilizce karşılığı hangisidir?', 'Neither my mother nor my father speaks English.', ['Either my mother or my father speaks English.', 'Neither my mother or my father doesn\'t speak English.', 'Both my mother and my father don\'t speak English.'], '\'Ne ... ne de\' \'neither ... nor\' ile karşılanır; yapı zaten olumsuz olduğu için fiil olumlu kalır.'),
  ('"Ya bu akşam ya da yarın sabah ararım." cümlesindeki \'ya ... ya da\' bağlacının İngilizce karşılığı hangisidir?', 'either ... or', ['neither ... nor', 'both ... and', 'whether ... and'], 'İki seçenekten birini bildiren \'ya ... ya da\' \'either ... or\' ile karşılanır.'),
  ('"Yağmur yağdığı için maç ertelendi." cümlesinde \'yağdığı için\' yerine ad öbeği kullanılarak yapılan doğru çeviri hangisidir?', 'The match was postponed because of the rain.', ['The match was postponed because the rain.', 'The match was postponed so the rain fell down.', 'The match was postponed although the rain.'], 'Ad öbeği (the rain) ile neden bildirmek için \'because of\' kullanılır.'),
  ('"Nereye gidersen git, seni bulurum." cümlesinin doğru İngilizce karşılığı hangisidir?', 'Wherever you go, I\'ll find you.', ['Whenever you go, I\'ll find you.', 'Where you will go, I\'ll find you there.', 'However you go, I\'ll find you.'], '\'Nereye ... -sen\' anlamı \'wherever\' ile verilir; \'whenever\' zaman, \'however\' biçim bildirir.'),
  ('"Hastaydım, bu yüzden okula gitmedim." cümlesinin doğru İngilizce karşılığı hangisidir?', 'I was ill, so I didn\'t go to school.', ['I was ill, but I didn\'t go to school.', 'I was ill because I didn\'t go to school.', 'Although I was ill, I didn\'t go to school.'], '\'Bu yüzden\' bir sonucu tanıtır ve eşgüdüm bağlacı \'so\' ile karşılanır.'),
  ('"Kardeşim partiye arkadaşlarıyla birlikte geldi." cümlesindeki \'ile birlikte\' anlamını veren edat öbeği hangisidir?', 'along with', ['instead of', 'apart from', 'in spite of'], '\'İle birlikte\' anlamı \'along with\' (ya da \'together with\') ile karşılanır.'),
  ('"Biz geldiğimizde film çoktan başlamıştı." cümlesindeki \'-dığımızda\' anlamını veren bağlaç hangisidir?', 'when', ['unless', 'whereas', 'so that'], '\'-dığında\' zaman bildirir ve \'when\' ile karşılanır: When we arrived, the film had already started.'),
  ('"I\'m going to study hard so that I can pass the exam." cümlesinin en uygun Türkçe karşılığı hangisidir?', 'Sınavı geçebilmek için çok çalışacağım.', ['Sınavı geçtiğim için çok çalışacağım.', 'Sınavı geçmeme rağmen yine de çok çalışacağım.', 'Sınavı geçersem çok çalışacağım.'], '\'So that\' amaç bildirir ve Türkçede \'-ebilmek için\' ile karşılanır.'),
